using I=long long;
using RGB=std::array<int,3>;
using Maps=std::array<std::array<RGB,256>,4>;
const std::array<std::string,4> names={"viridis","plasma","inferno","magma"};
std::string contents(const std::string& p){std::ifstream f(p,std::ios::binary);if(!f)throw std::runtime_error("cannot read "+p);return {(std::istreambuf_iterator<char>(f)),{}};}
int byte(const std::string& token){
 // Independent exact decimal quantization agrees with IEEE binary64*255 on
 // the pinned six-decimal primary data. No Python code is executed.
 if(token.size()!=8||(token[0]!='0'&&token[0]!='1')||token[1]!='.')throw std::runtime_error("pinned six-decimal source required");
 auto dot=token.find('.');if(dot==std::string::npos)throw std::runtime_error("decimal token");
 I numerator=0,denominator=1;for(char c:token){if(c=='.')continue;if(c<'0'||c>'9')throw std::runtime_error("decimal syntax");numerator=numerator*10+c-'0';}
 for(std::size_t j=dot+1;j<token.size();++j)denominator*=10;
 const I exact=numerator*255/denominator;
 double value=0;const auto parsed=std::from_chars(token.data(),token.data()+token.size(),value);
 if(parsed.ec!=std::errc{}||parsed.ptr!=token.data()+token.size()||!std::isfinite(value)||value<0||value>1)throw std::runtime_error("floating source token");
 const auto binary=static_cast<I>(value*255.0);
 if(exact!=binary||exact<0||exact>255)throw std::runtime_error("quantization discrepancy requires review");
 return static_cast<int>(exact);
}
Maps read_maps(const std::string& path,std::vector<std::uint64_t>* nominal=nullptr){const auto text=contents(path);Maps out{};if(nominal)nominal->clear();
 for(std::size_t p=0;p<4;++p){const auto label="_"+names[p]+"_data = [";const auto found=text.find(label);if(found==std::string::npos)throw std::runtime_error("palette absent");const auto start=found+label.size()-1;std::size_t end=start;int depth=0;do{if(text[end]=='[')++depth;if(text[end]==']')--depth;++end;if(end>=text.size())throw std::runtime_error("unterminated data");}while(depth);
  const auto data=text.substr(start,end-start);const std::regex number(R"([0-9]+\.[0-9]+)");std::vector<std::string> tokens;
  for(std::sregex_iterator it(data.begin(),data.end(),number),last;it!=last;++it)tokens.push_back(it->str());
  if(tokens.size()!=768)throw std::runtime_error("not 256 RGB entries");
  for(std::size_t i=0;i<256;++i)for(std::size_t c=0;c<3;++c){const auto& token=tokens[3*i+c];out[p][i][c]=byte(token);if(nominal){double value=0;const auto parsed=std::from_chars(token.data(),token.data()+token.size(),value);if(parsed.ec!=std::errc{})throw std::runtime_error("source float parse");nominal->push_back(std::bit_cast<std::uint64_t>(value));}}
 }
 return out;
}
I packed(const RGB& v){return (I(v[0])<<16)|(I(v[1])<<8)|I(v[2]);}
void pair_tree(const std::array<RGB,256>& colors,int lo,int hi){
 if(hi-lo==1){std::cout<<((packed(colors[2*lo+1])<<24)|packed(colors[2*lo]));return;}
 const int mid=(lo+hi)/2;std::cout<<"if index<"<<mid<<" {";pair_tree(colors,lo,mid);std::cout<<"}else{";pair_tree(colors,mid,hi);std::cout<<"}";
}
void emit_lut(const Maps& maps){
 std::cout<<"// Generated by canonical_palette_reference.cpp from pinned BIDS/colormap.\n// Source bc549477db0c12b54a5928087552ad2cf274980f; CC0-1.0.\n// RGB8 = floor(255*canonical channel); 256 entries per palette.\n// Balanced immutable packed-pair lookup: no runtime arrays or allocations.\n";
 for(std::size_t p=0;p<4;++p){std::cout<<"fn cm_lut_"<<names[p]<<"(index:i64)->i64 {\n ";pair_tree(maps[p],0,128);std::cout<<"\n}\n";}
 std::cout<<"pub fn palette_lut_rgb8(palette:i64,index:i64)->i64 {\n if palette<1 || palette>4 || index<0 || index>255 {return -1}\n let pair_index=index>>1\n let pair=if palette==1 {cm_lut_viridis(pair_index)}else if palette==2 {cm_lut_plasma(pair_index)}else if palette==3 {cm_lut_inferno(pair_index)}else{cm_lut_magma(pair_index)}\n (pair>>((index&1)*24))&16777215\n}\n";
}
void emit_legacy(const Maps& maps){
 std::cout<<"//@ run-pass\n//@ requires: madaros\nuse viz::colormap::{viridis_u32,plasma_u32,inferno_u32,magma_u32}\nfn main() with IO,Mut,Div,Panic {\n var p:i64=1\n while p<=4 {\n  var i:i64=0\n  while i<256 {\n   let t=((i as f64)+0.5)/256.0\n   let rgb:i64=(if p==1 {viridis_u32(t)}else if p==2 {plasma_u32(t)}else if p==3 {inferno_u32(t)}else{magma_u32(t)}) as i64\n   print(\"PALETTE_LEGACY \");print(p);print(\" \");print(i);print(\" \");println(rgb)\n   i=i+1\n  }\n  p=p+1\n }\n println(\"PALETTE_LEGACY_ROWS_COMPLETE\")\n let middle:i64=viridis_u32(0.5) as i64\n assert(middle=="<<packed(maps[0][128])<<")\n println(\"PALETTE_LEGACY_PASS\")\n}\n";
}
void check_legacy(const Maps& maps,const std::string& path){std::istringstream lines(contents(path));std::string row;I count=0;bool complete=false;I mismatches=0;
 while(std::getline(lines,row)){std::istringstream in(row);std::string tag;in>>tag;if(tag=="PALETTE_LEGACY"){I p,index,rgb;in>>p>>index>>rgb;if(!in||p!=count/256+1||index!=count%256||p<1||p>4)throw std::runtime_error("row identity/count");const I expected=packed(maps[p-1][index]);if(rgb!=expected){if(mismatches<8)std::cerr<<"palette="<<p<<" bin="<<index<<" actual="<<rgb<<" expected="<<expected<<'\n';++mismatches;}++count;}if(tag=="PALETTE_LEGACY_ROWS_COMPLETE")complete=true;}
 if(count!=1024||!complete)throw std::runtime_error("incomplete canonical rows");
 if(mismatches)throw std::runtime_error("canonical RGB mismatches="+std::to_string(mismatches));
 std::cout<<"CANONICAL_PALETTE_LEGACY_REFERENCE_PASS palettes=4 bins=1024 exact_decimal_and_binary64_quantization\n";
}
using PixelMap=std::map<std::pair<I,I>,I>;
using Glyphs=std::array<std::uint64_t,128>;
Glyphs font(){const auto text=contents("tests/reference/data/font8x8_basic.h");Glyphs out{};std::array<bool,128> seen{};
 const std::regex line(R"(\{([^{}]+)\},?\s*// U\+([0-9A-Fa-f]{4}))"),byte_re(R"(0x([0-9A-Fa-f]+))");
 for(std::sregex_iterator it(text.begin(),text.end(),line),end;it!=end;++it){const auto ch=std::stoul((*it)[2],nullptr,16);if(ch>=128||seen[ch])throw std::runtime_error("primary font identity");seen[ch]=true;const std::string row=(*it)[1];unsigned y=0;for(std::sregex_iterator b(row.begin(),row.end(),byte_re);b!=end;++b){if(y>=8)throw std::runtime_error("primary font rows");out[ch]|=std::stoull((*b)[1],nullptr,16)<<(8*y);++y;}if(y!=8)throw std::runtime_error("primary font row count");}
 for(bool present:seen){if(!present)throw std::runtime_error("missing primary font glyph");}
 return out;
}
I cell_coordinate(const std::string& token){const double v=std::stod(token);const I result=static_cast<I>(v+0.5);if(v!=static_cast<double>(result)-0.5)throw std::runtime_error("pixel-cell boundary");return result;}
void fill(PixelMap& p,I x,I y,I w,I h,I rgb){if(w<=0||h<=0||x<0||y<0||x+w>720||y+h>480)throw std::runtime_error("oracle rect bounds");for(I py=y;py<y+h;++py)for(I px=x;px<x+w;++px){if(rgb)p[{px,py}]=rgb;}}
std::string attr(const std::string& tag,const std::string& name){const std::regex r("(?:^|[[:space:]])"+name+"=\"([^\"]*)\"");std::smatch m;if(!std::regex_search(tag,m,r))throw std::runtime_error("missing attribute "+name);return m[1];}
void check_figure(const Maps& maps,const std::string& path,const std::string& ppm){
 const auto all=contents(path);if(all.find("CANONICAL_PALETTES_PASS")==std::string::npos)throw std::runtime_error("native completion");
 if(all.find("REJECT_COLORBAR_BEGIN\nREJECT_COLORBAR_END")==std::string::npos||all.find("<!-- REJECT_HEATMAP_BEGIN -->\n<!-- REJECT_HEATMAP_END -->")==std::string::npos)throw std::runtime_error("invalid late request emitted bytes");
 I lut_count=0,policy_count=0,million=-1;PixelMap actual;std::istringstream rows(all);std::string row;
 const std::array<std::array<I,4>,8> policy{{{{0,0x112233,-1,1}},{{0,packed(maps[0][0]),0,0}},{{0,packed(maps[0][128]),128,0}},{{0,packed(maps[0][255]),255,0}},{{0,0x445566,-1,2}},{{0,0x778899,-1,3}},{{3,0,-1,-1}},{{3,0,-1,-1}}}};
 while(std::getline(rows,row)){std::istringstream in(row);std::string tag;in>>tag;
  if(tag=="PALETTE_LUT"){I p,i,rgb;in>>p>>i>>rgb;if(!in||p!=lut_count/256+1||i!=lut_count%256||rgb!=packed(maps[p-1][i]))throw std::runtime_error("canonical LUT row mismatch");++lut_count;}
  if(tag=="PALETTE_POLICY"){I index;std::array<I,4> got{};in>>index>>got[0]>>got[1]>>got[2]>>got[3];if(!in||index!=policy_count||index<0||index>=8||got!=policy[index])throw std::runtime_error("special color classification/reset mismatch");++policy_count;}
  if(tag=="PALETTE_MILLION"){in>>million;if(!in)throw std::runtime_error("million record");}
  if(tag=="PALETTE_PIXEL"){I x,y,rgb;in>>x>>y>>rgb;if(!in||x<0||x>=720||y<0||y>=480||rgb<1||rgb>0xffffff||!actual.emplace(std::pair{x,y},rgb).second)throw std::runtime_error("native pixel record");}
 }
 I checksum=0;for(I i=0;i<1000000;++i)checksum=(checksum+packed(maps[0][i%256]))%1000000007;
 if(lut_count!=1024||policy_count!=8||million!=checksum)throw std::runtime_error("LUT/policy/million completeness");
 const std::regex bar_re(R"re(<rect data-colorbar-step="([0-9]+)" data-palette-index="([0-9]+)" x="([0-9.-]+)" y="([0-9.-]+)" width="([0-9]+)" height="([0-9]+)" fill="rgb\(([0-9]+),([0-9]+),([0-9]+)\)"/>)re");
 using Bar=std::array<I,7>;std::vector<Bar> bars,wanted_bars;PixelMap expected;
 for(std::sregex_iterator it(all.begin(),all.end(),bar_re),end;it!=end;++it){const auto&m=*it;bars.push_back({std::stoll(m[1]),std::stoll(m[2]),cell_coordinate(m[3]),cell_coordinate(m[4]),std::stoll(m[5]),std::stoll(m[6]),(std::stoll(m[7])<<16)|(std::stoll(m[8])<<8)|std::stoll(m[9])});}
 for(I p=0;p<4;++p)for(I i=0;i<256;++i)wanted_bars.push_back({i,i,80+2*i,20+80*p,2,16,packed(maps[p][i])});
 wanted_bars.push_back({0,128,80,340,512,16,packed(maps[0][128])});
 if(bars!=wanted_bars)throw std::runtime_error("colorbar canonical colors/shared pixel-cell geometry");
 for(const auto& v:wanted_bars)fill(expected,v[2],v[3],v[4],v[5],v[6]);
 const std::regex heat_re(R"re(<rect data-source-index="([0-9]+)" data-source-row="([0-9]+)" data-source-col="([0-9]+)" data-color-class="([0-9]+)" data-palette-index="([0-9-]+)" x="([0-9.-]+)" y="([0-9.-]+)" width="([0-9]+)" height="([0-9]+)" fill="rgb\(([0-9]+),([0-9]+),([0-9]+)\)"/>)re");
 using Heat=std::array<I,10>;std::vector<Heat> heat,wanted_heat;
 for(std::sregex_iterator it(all.begin(),all.end(),heat_re),end;it!=end;++it){const auto&m=*it;heat.push_back({std::stoll(m[1]),std::stoll(m[2]),std::stoll(m[3]),std::stoll(m[4]),std::stoll(m[5]),cell_coordinate(m[6]),cell_coordinate(m[7]),std::stoll(m[8]),std::stoll(m[9]),(std::stoll(m[10])<<16)|(std::stoll(m[11])<<8)|std::stoll(m[12])});}
 const std::array<double,10> values{-2,-1,-.5,0,.5,1,2,0,0,0};
 for(I i=0;i<10;++i){const I r=i/5,c=i%5;I kind=0,bin=-1,rgb=0;
  if(i==7||i==9){kind=3;rgb=0x808080;}else if(values[i]<-1){kind=1;rgb=0xff00ff;}else if(values[i]>1){kind=2;rgb=0x00ffff;}else{bin=values[i]==1?255:static_cast<I>((values[i]+1)*128);rgb=packed(maps[0][bin]);}
  const I x=80+c*512/5,w=80+(c+1)*512/5-x;wanted_heat.push_back({i,r,c,kind,bin,x,420+r*16,w,16,rgb});fill(expected,x,420+r*16,w,16,rgb);
 }
 if(heat!=wanted_heat)throw std::runtime_error("heatmap canonical colors/missing/under/over/strided provenance");
 using Text=std::tuple<I,I,I,std::string>;std::vector<Text> texts,wanted_text;
 const std::regex text_re(R"re(<text x="([0-9-]+)" y="([0-9-]+)" font-family="monospace" font-size="8" textLength="([0-9]+)" lengthAdjust="spacingAndGlyphs" fill="rgb\(255,255,255\)">([^<]*)</text>)re");
 for(std::sregex_iterator it(all.begin(),all.end(),text_re),end;it!=end;++it){const auto&m=*it;const I x=std::stoll(m[1]),y=std::stoll(m[2]),w=std::stoll(m[3]);if(x<0||x+w>720||y-7<0||y+1>480||w!=static_cast<I>(m[4].length())*8)throw std::runtime_error("actual text cell bounds");texts.emplace_back(x,y,w,m[4]);}
 for(I p=0;p<4;++p){wanted_text.emplace_back(36,51+80*p,88,"-1.00000e+0");wanted_text.emplace_back(551,51+80*p,80,"1.00000e+0");wanted_text.emplace_back(80,15+80*p,static_cast<I>(names[p].size())*8,names[p]);}
 wanted_text.emplace_back(295,371,80,"2.50000e+0");wanted_text.emplace_back(80,335,56,"viridis");
 if(texts!=wanted_text)throw std::runtime_error("true domain/name labels or fitted text placement");
 // Existing pinned public-domain bitmap data, read as data; no renderer reuse.
 const auto glyphs=font();for(const auto&[x,baseline,w,text]:wanted_text){(void)w;for(std::size_t k=0;k<text.size();++k){const auto bits=glyphs[static_cast<unsigned char>(text[k])];for(I y=0;y<8;++y)for(I c=0;c<8;++c)if((bits>>(8*y+c))&1)expected[{x+static_cast<I>(k)*8+c,baseline-7+y}]=0xffffff;}}
 if(actual!=expected)throw std::runtime_error("actual Canvas canonical RGB/geometry/primary-font pixels mismatch");
 const std::regex group_re(R"(<g [^>]*>)");I groups=0;
 for(std::sregex_iterator it(all.begin(),all.end(),group_re),end;it!=end;++it){const auto tag=it->str();const bool bar=groups<5;if(groups>=6)throw std::runtime_error("extra group");
  if(attr(tag,"data-dynamic-series")!=(bar?"canonical-colorbar":"heatmap")||attr(tag,"data-palette-source")!="BIDS/colormap@bc549477db0c12b54a5928087552ad2cf274980f"||attr(tag,"data-palette-rgb8")!="floor-255-channel"||attr(tag,"data-palette-bins")!="floor-256-t-endpoint-255")throw std::runtime_error("shared canonical policy metadata");
  const I p=groups<4?groups:0;if(attr(tag,"data-palette")!=names[p])throw std::runtime_error("palette identity");
  const double lo=std::stod(attr(tag,"data-color-min")),hi=std::stod(attr(tag,"data-color-max"));if(lo!=(groups<4?-1:groups==4?2.5:-1)||hi!=(groups<4?1:groups==4?2.5:1))throw std::runtime_error("raw domain metadata");
  if(bar){if(attr(tag,"data-orientation")!="increasing-left-to-right"||attr(tag,"data-constant-domain")!=(groups==4?"true":"false"))throw std::runtime_error("colorbar direction/constant policy");}else{if(attr(tag,"data-missing-policy")!="configured-color"||attr(tag,"data-row-order")!="top-to-bottom"||std::stoll(attr(tag,"data-under-rgb8"))!=0xff00ff||std::stoll(attr(tag,"data-over-rgb8"))!=0x00ffff||std::stoll(attr(tag,"data-missing-rgb8"))!=0x808080)throw std::runtime_error("special color metadata");}
  ++groups;
 }
 if(groups!=6)throw std::runtime_error("group completeness");
 if(!ppm.empty()){std::ofstream image(ppm,std::ios::binary);if(!image)throw std::runtime_error("PPM output");image<<"P6\n720 480\n255\n";for(I y=0;y<480;++y)for(I x=0;x<720;++x){const auto it=actual.find({x,y});const I rgb=it==actual.end()?0:it->second;const char b[]{static_cast<char>((rgb>>16)&255),static_cast<char>((rgb>>8)&255),static_cast<char>(rgb&255)};image.write(b,3);}if(!image)throw std::runtime_error("PPM write");std::ofstream rle(ppm+".rle");if(!rle)throw std::runtime_error("actual RLE output");rle<<"CANVAS_SIZE 720 480\n";I start=0,length=0,last=0;for(I i=0;i<720*480;++i){const auto it=actual.find({i%720,i/720});const I rgb=it==actual.end()?0:it->second;if(length&&rgb!=last){rle<<"CANVAS_RUN "<<start<<' '<<length<<' '<<last<<'\n';start=i;length=0;}if(!length)last=rgb;++length;}if(length)rle<<"CANVAS_RUN "<<start<<' '<<length<<' '<<last<<'\n';rle<<"CANVAS_END\n";if(!rle)throw std::runtime_error("actual RLE write");}
 std::cout<<"CANONICAL_PALETTE_FIGURE_REFERENCE_PASS lut=1024 policies=8 million=1000000 colorbar_rects="<<bars.size()<<" heatmap_cells="<<heat.size()<<" texts="<<texts.size()<<" actual_canvas_pixels="<<actual.size()<<"\n";
}
std::vector<std::array<I,3>> historical_rows(const std::string& path){std::istringstream in(contents(path));std::string row;std::vector<std::array<I,3>> out;bool complete=false;while(std::getline(in,row)){std::istringstream fields(row);std::string tag;fields>>tag;if(tag=="PALETTE_LEGACY"){std::array<I,3> v{};fields>>v[0]>>v[1]>>v[2];if(!fields||v[0]!=static_cast<I>(out.size()/256+1)||v[1]!=static_cast<I>(out.size()%256))throw std::runtime_error("historical row identity");out.push_back(v);}if(tag=="PALETTE_LEGACY_ROWS_COMPLETE")complete=true;}if(!complete||out.size()!=1024)throw std::runtime_error("historical native rows incomplete");return out;}
int main(int argc,char**argv){try{if(argc<3)throw std::runtime_error("usage: --emit-lut|--emit-legacy|--legacy|--sources PRIMARY [SECOND]");const auto maps=read_maps(argv[2]);const std::string mode=argv[1];if(mode=="--emit-lut")emit_lut(maps);else if(mode=="--emit-legacy")emit_legacy(maps);else if(mode=="--legacy"&&argc==4)check_legacy(maps,argv[3]);else if(mode=="--figure"&&(argc==4||argc==5))check_figure(maps,argv[3],argc==5?argv[4]:"");else if(mode=="--approx"&&argc==5){if(historical_rows(argv[3])!=historical_rows(argv[4]))throw std::runtime_error("explicit approximation differs from original native output");std::cout<<"APPROX_COMPATIBILITY_REFERENCE_PASS historical_native_rows=1024\n";}else if(mode=="--sources"&&argc==4){std::vector<std::uint64_t> a,b;const auto first=read_maps(argv[2],&a);const auto second=read_maps(argv[3],&b);if(first!=second||a!=b)throw std::runtime_error("BIDS/Matplotlib canonical floats or RGB8 disagreement");std::cout<<"CANONICAL_PRIMARY_CONCORDANCE_PASS palettes=4 bins=1024 float_channels=3072 bit_identical_and_RGB8\n";}else throw std::runtime_error("arguments");return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
